/**
 * Glitchhook Production Engine v15.0 (Strict Video Mapping & Fast Buffer Fix)
 */
(function() {
  const MASTER_CONFIG = {
    sheetUrl: "YOUR_GOOGLE_APPS_SCRIPT_URL", 
    couponCode: "VIPFREE",                     
    discountHeadline: "FREE SHIPPING",         
    discountSubtext: "ক্যাশ অন ডেলিভারিতে চেক করে টাকা দিন!",

    githubBaseUrl: "https://raw.githubusercontent.com/for-presence/tfs/main/",

    // 🎥 এখানে শুধু যে যেটার জন্য ভিডিও চান সেটার ফাইলের নাম দিন। 
    // ২ নম্বরে ভিডিও না দিতে চাইলে লিস্টে ১টাই রাখবেন, ২ নম্বরে কোনো ভিডিও লোড হবে না!
    productVideos: [
      {
        primary: "https://nutrwuochxazypmjbjdh.supabase.co/storage/v1/object/public/video/SF22Qx3%20-%20Imgur.mp4",
        trust: "proof1.mp4"
      }
      // ২ নম্বর প্রোডাক্টের ভিডিও দরকার নেই তাই এখানে কিছু দেওয়া হয়নি!
    ],

    enableScratchCard: true,
    enableTimelineWidget: true,
    autoApplyCoupon: true
  };

  function getMediaUrl(filename) {
    if (!filename) return null;
    if (filename.startsWith("http://") || filename.startsWith("https://")) {
      return filename;
    }
    return MASTER_CONFIG.githubBaseUrl + filename;
  }

  let state = {
    hasSwitchedVideo: false,
    popupShown: false,
    clickCount: 0,
    startTime: Date.now(),
    lastScrollY: window.pageYOffset,
    maxScrollDepth: 0
  };

  function sendAnalytics(eventType, extraData = {}) {
    if (MASTER_CONFIG.sheetUrl && !MASTER_CONFIG.sheetUrl.includes("YOUR_GOOGLE")) {
      navigator.sendBeacon(MASTER_CONFIG.sheetUrl, JSON.stringify({
        eventType: eventType,
        pageUrl: window.location.href,
        timeSpentSeconds: Math.floor((Date.now() - state.startTime) / 1000),
        totalBuyClicks: state.clickCount,
        maxScrollDepthPx: state.maxScrollDepth,
        timestamp: new Date().toLocaleString("en-US", {timeZone: "Asia/Dhaka"}),
        ...extraData
      }));
    }
  }

  function findCheckoutForm() {
    return document.querySelector(
      'form.checkout, form.woocommerce-checkout, #order-form, .order-form, .checkout-form, ' +
      '#customer_details, form[action*="checkout"], .woocommerce-billing-fields, .wc-delivery-form'
    ) || document.querySelector('input[name*="billing_phone"], input[type="tel"], input[name*="phone"]')?.closest('form');
  }

  function applyCouponCode() {
    if (!MASTER_CONFIG.autoApplyCoupon) return;
    const couponInput = document.querySelector('input[name="coupon_code"], input[id*="coupon"], input[placeholder*="coupon"], input[placeholder*="কুপন"]');
    if (couponInput) {
      couponInput.value = MASTER_CONFIG.couponCode;
      const applyBtn = couponInput.nextElementSibling || couponInput.parentNode.querySelector('button, input[type="submit"]');
      if (applyBtn && typeof applyBtn.click === 'function') {
        applyBtn.click();
      }
    }
  }

  function scrollToCheckout() {
    applyCouponCode();
    const checkoutForm = findCheckoutForm();
    if (checkoutForm) {
      checkoutForm.scrollIntoView({ behavior: 'smooth', block: 'center' });
      setTimeout(() => {
        const phoneOrNameInput = checkoutForm.querySelector('input[type="tel"], input[name*="phone"], input[name*="billing_phone"], input[name*="name"], input[type="text"]');
        if (phoneOrNameInput) phoneOrNameInput.focus();
      }, 500);
    } else {
      const cartBtn = document.querySelector('button[name="add"], .single_add_to_cart_button, #add-to-cart, .btn-cart, button.cart, .add-to-cart-btn');
      if (cartBtn) cartBtn.click();
      window.scrollTo({ top: document.body.scrollHeight, behavior: 'smooth' });
    }
  }

  // CHECKOUT TIMELINE WIDGET
  function injectPsychologicalCheckoutWidgets() {
    if (!MASTER_CONFIG.enableTimelineWidget) return;
    const checkoutForm = findCheckoutForm();
    if (!checkoutForm || document.getElementById('gh-checkout-timeline')) return;

    const today = new Date();
    const deliveryDate = new Date(today);
    deliveryDate.setDate(today.getDate() + 2);

    const monthNames = ["জানুয়ারি", "ফেব্রুয়ারি", "মার্চ", "এপ্রিল", "মে", "জুন", "জুলাই", "আগস্ট", "সেপ্টেম্বর", "অক্টোবর", "নভেম্বর", "ডিসেম্বর"];
    const formattedDate = `${deliveryDate.getDate()} ${monthNames[deliveryDate.getMonth()]}`;

    const widgetBox = document.createElement('div');
    widgetBox.id = "gh-checkout-timeline";
    widgetBox.style.cssText = `
      background: #18181b; border: 1.5px solid #ffcc00;
      border-radius: 16px; padding: 16px; margin: 15px 0 20px 0; color: #ffffff;
      font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; font-size: 13px;
      box-shadow: 0 10px 30px rgba(0,0,0,0.6); position: relative; box-sizing: border-box;
    `;

    widgetBox.innerHTML = `
      <div style="margin-bottom: 12px;">
        <div style="display: flex; justify-content: space-between; font-size: 11px; font-weight: 800; color: #ffcc00; margin-bottom: 4px;">
          <span>অর্ডার অগ্রগতি: ৮০%</span>
          <span>আর মাত্র ১টি স্টেপ!</span>
        </div>
        <div style="width: 100%; height: 8px; background: rgba(255,255,255,0.1); border-radius: 10px; overflow: hidden;">
          <div style="width: 80%; height: 100%; background: linear-gradient(90deg, #ffcc00, #00ffcc); border-radius: 10px;"></div>
        </div>
      </div>

      <div style="display: flex; align-items: center; gap: 10px;">
        <span style="font-size: 24px;">🚚</span>
        <div>
          <div style="font-weight: 800; color: #00ffcc; font-size: 14px;">গ্যারান্টিড এক্সপ্রেস ডেলিভারি!</div>
          <div style="color: #a1a1aa; font-size: 12px; margin-top: 2px;">
            আজ অর্ডার করলে <b>${formattedDate}</b>-এর মধ্যে ডেলিভারি পাবেন। 
            <span style="color: #ffcc00; font-weight: 700;">${MASTER_CONFIG.discountSubtext}</span>
          </div>
        </div>
      </div>
    `;

    checkoutForm.parentNode.insertBefore(widgetBox, checkoutForm);
  }

  // SCRATCH CARD MODAL
  function triggerScratchCardPopup(triggerReason) {
    if (!MASTER_CONFIG.enableScratchCard || state.popupShown) return;
    state.popupShown = true;
    sendAnalytics("SCRATCH_MODAL_TRIGGERED", { triggerReason: triggerReason });

    const overlay = document.createElement('div');
    overlay.id = "glitchhook-scratch-modal";
    overlay.style.cssText = `
      position: fixed; top: 0; left: 0; width: 100%; height: 100%;
      background: rgba(0, 0, 0, 0.92); z-index: 99999999;
      display: flex; align-items: center; justify-content: center; padding: 20px;
      backdrop-filter: blur(14px); -webkit-backdrop-filter: blur(14px);
      box-sizing: border-box;
    `;

    overlay.innerHTML = `
      <div style="background: rgba(24, 24, 27, 0.98); color: #ffffff; padding: 26px 22px; border-radius: 24px; text-align: center; max-width: 350px; width: 100%; border: 1px solid rgba(255, 204, 0, 0.5); box-shadow: 0 25px 60px rgba(0,0,0,0.9); font-family: -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif; position: relative;">
        
        <div style="display: inline-flex; align-items: center; gap: 6px; background: rgba(0, 255, 204, 0.12); border: 1px solid rgba(0, 255, 204, 0.4); padding: 4px 12px; border-radius: 30px; margin-bottom: 12px;">
          <span style="font-size: 12px;">🎰</span>
          <span style="font-size: 10px; font-weight: 800; color: #00ffcc; text-transform: uppercase;">LUCKY REWARD CARD</span>
        </div>

        <h3 style="margin: 0 0 6px 0; color: #ffffff; font-size: 19px; font-weight: 900; line-height: 1.2;">
          কার্ডটি <span style="color: #ffcc00;">ঘষে গোপন ছাড়</span> বের করুন! ⚡
        </h3>
        <p style="margin: 0 0 16px 0; font-size: 12px; color: #a1a1aa;">
          আঙুল দিয়ে নিচের বক্সে ঘষলেই আনলক হবে আপনার স্পেশাল কুপন।
        </p>

        <div style="position: relative; width: 260px; height: 110px; margin: 0 auto 16px auto; border-radius: 16px; overflow: hidden; box-shadow: inset 0 0 15px rgba(0,0,0,0.8); border: 1px dashed #ffcc00;">
          <div style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; background: #121214; display: flex; flex-direction: column; align-items: center; justify-content: center; color: #00ffcc; font-weight: 900;">
            <span style="font-size: 20px; color: #ffcc00;">🎉 ${MASTER_CONFIG.discountHeadline}</span>
            <span style="font-size: 12px; color: #ffffff; margin-top: 4px;">COUPON: <b style="letter-spacing: 1px; color: #00ffcc;">${MASTER_CONFIG.couponCode}</b></span>
          </div>

          <canvas id="gh-scratch-canvas" width="260" height="110" style="position: absolute; top: 0; left: 0; cursor: pointer; touch-action: none;"></canvas>
        </div>

        <button id="gh-scratch-claim-btn" disabled style="background: #3f3f46; color: #a1a1aa; border: none; padding: 14px 20px; border-radius: 50px; font-weight: 900; font-size: 14px; width: 100%; cursor: not-allowed; transition: all 0.3s ease;">
          আগে কার্ডটি ঘষুন 👆
        </button>

        <p id="gh-scratch-close" style="margin: 14px 0 0 0; font-size: 11px; color: #71717a; cursor: pointer; text-decoration: underline;">
          আমি অফার ছাড়াই অর্ডার করব
        </p>
      </div>
    `;

    document.body.appendChild(overlay);

    const canvas = document.getElementById('gh-scratch-canvas');
    const ctx = canvas.getContext('2d');
    const claimBtn = document.getElementById('gh-scratch-claim-btn');

    ctx.fillStyle = '#71717a';
    ctx.fillRect(0, 0, 260, 110);
    ctx.fillStyle = '#e4e4e7';
    ctx.font = 'bold 13px sans-serif';
    ctx.textAlign = 'center';
    ctx.fillText('✨ এখানে আঙুল দিয়ে ঘষুন ✨', 130, 60);

    let isScratching = false;
    let scratchedPixels = 0;

    function scratch(e) {
      if (!isScratching) return;
      const rect = canvas.getBoundingClientRect();
      const x = (e.touches ? e.touches[0].clientX : e.clientX) - rect.left;
      const y = (e.touches ? e.touches[0].clientY : e.clientY) - rect.top;

      ctx.globalCompositeOperation = 'destination-out';
      ctx.beginPath();
      ctx.arc(x, y, 18, 0, Math.PI * 2);
      ctx.fill();

      scratchedPixels++;
      if (scratchedPixels > 25 && claimBtn.disabled) {
        claimBtn.disabled = false;
        claimBtn.style.background = 'linear-gradient(135deg, #ffcc00 0%, #ff9900 100%)';
        claimBtn.style.color = '#000000';
        claimBtn.style.cursor = 'pointer';
        claimBtn.innerText = 'অফারটি ব্যবহার করে অর্ডার করুন ⚡';
        claimBtn.style.boxShadow = '0 8px 25px rgba(255, 204, 0, 0.4)';
      }
    }

    canvas.addEventListener('mousedown', () => isScratching = true);
    canvas.addEventListener('mouseup', () => isScratching = false);
    canvas.addEventListener('mousemove', scratch);

    canvas.addEventListener('touchstart', () => isScratching = true);
    canvas.addEventListener('touchend', () => isScratching = false);
    canvas.addEventListener('touchmove', scratch);

    claimBtn.addEventListener('click', () => {
      if (claimBtn.disabled) return;
      sendAnalytics("SCRATCH_COUPON_CLAIMED");
      overlay.remove();
      scrollToCheckout();
    });

    document.getElementById('gh-scratch-close').addEventListener('click', () => {
      overlay.remove();
    });
  }

  // VIDEO ENGINE
  function switchToTrustVideo(videoEl, trustUrl, reason) {
    if (state.hasSwitchedVideo || !trustUrl) return;
    state.hasSwitchedVideo = true;

    sendAnalytics("VIDEO_SWITCHED", { 
      reason: reason,
      timeBeforeSwitchSeconds: Math.floor((Date.now() - state.startTime) / 1000) 
    });

    if (videoEl) {
      videoEl.src = trustUrl;
      videoEl.load();
      videoEl.play().catch(() => {});
    }
  }

  function initVideoEngine() {
    const allImages = document.querySelectorAll('img');
    let targetImages = [];

    for (let img of allImages) {
      let className = (img.className + " " + img.id + " " + img.parentElement.className).toLowerCase();
      if (className.includes('logo') || className.includes('icon') || className.includes('avatar') || className.includes('thumb')) continue;
      if (className.includes('header') || className.includes('banner') || className.includes('hero') || className.includes('product') || className.includes('gallery') || className.includes('featured')) {
        targetImages.push(img);
      }
    }

    if (targetImages.length === 0) return;

    let mainVideoEl = null;
    let mainTrustUrl = null;

    targetImages.forEach((targetImg, index) => {
      // 🔒 STRICT CHECK: If no config exists for this index, DO NOT REPLACE
      let assignedVideo = MASTER_CONFIG.productVideos[index];
      if (!assignedVideo || !assignedVideo.primary) return;

      const primaryUrl = getMediaUrl(assignedVideo.primary);
      const trustUrl = getMediaUrl(assignedVideo.trust);

      if (!primaryUrl) return;

      const parentContainer = targetImg.parentElement;
      const computedStyle = window.getComputedStyle(targetImg);
      const imgHeight = targetImg.clientHeight || targetImg.naturalWidth || '400px';
      const imgBorderRadius = computedStyle.borderRadius || '16px';

      targetImg.style.display = 'none';

      const wrapper = document.createElement('div');
      wrapper.id = "glitchhook-video-box-" + index;
      wrapper.style.cssText = `
        position: relative; width: 100%; height: 100%;
        min-height: ${imgHeight > 100 ? imgHeight + 'px' : '380px'};
        background: #000; border-radius: ${imgBorderRadius};
        overflow: hidden; display: flex; align-items: center; justify-content: center;
        margin-bottom: 15px; transform: translateZ(0); will-change: transform;
      `;

      wrapper.innerHTML = `
        <video 
          id="glitchhook-vid-${index}"
          src="${primaryUrl}" autoplay muted loop playsinline webkit-playsinline 
          preload="auto" style="width: 100%; height: 100%; object-fit: cover; position: absolute; top: 0; left: 0; pointer-events: none; transform: translateZ(0);">
        </video>
        <div class="glitchhook-click-layer" style="position: absolute; top: 0; left: 0; width: 100%; height: 100%; z-index: 10; cursor: pointer;"></div>
      `;

      const videoEl = wrapper.querySelector('video');
      if (index === 0) {
        mainVideoEl = videoEl;
        mainTrustUrl = trustUrl;
      }

      videoEl.play().catch(() => {});

      if (index === 0) {
        const btn = document.createElement('button');
        btn.innerHTML = "BUY NOW ⚡";
        btn.style.cssText = `
          position: absolute; bottom: 20px; right: 20px;
          background: #ffcc00; color: #000; border: 2px solid #fff;
          padding: 12px 26px; border-radius: 40px; font-weight: 900;
          font-size: 14px; cursor: pointer; z-index: 99999;
          box-shadow: 0 8px 25px rgba(0,0,0,0.6);
        `;

        const handleAction = (e) => {
          if (e) { e.preventDefault(); e.stopPropagation(); }
          state.clickCount++;
          sendAnalytics("BUY_NOW_CLICK", { source: "video_overlay_button" });
          scrollToCheckout();
        };

        btn.addEventListener('click', handleAction);
        wrapper.querySelector('.glitchhook-click-layer').addEventListener('click', handleAction);
        wrapper.appendChild(btn);
      }

      parentContainer.appendChild(wrapper);
    });

    // Hesitation timer
    setTimeout(() => {
      if (!state.popupShown && state.maxScrollDepth < 200) {
        triggerScratchCardPopup("hesitation_time_out");
      }
    }, 12000);

    window.addEventListener('scroll', () => {
      let currentY = window.pageYOffset;
      injectPsychologicalCheckoutWidgets();

      if (currentY > state.maxScrollDepth) {
        state.maxScrollDepth = currentY;
      }

      if (state.maxScrollDepth > 150 && (state.lastScrollY - currentY > 20) && !state.hasSwitchedVideo && mainTrustUrl) {
        switchToTrustVideo(mainVideoEl, mainTrustUrl, "scroll_up_gesture");
      }

      if (state.maxScrollDepth > 220 && (state.lastScrollY - currentY > 35) && currentY < 180) {
        triggerScratchCardPopup("exit_scroll_motion");
      }

      state.lastScrollY = currentY;
    }, { passive: true });

    sendAnalytics("VIDEO_IMPRESSION");
  }

  if (document.readyState === 'complete' || document.readyState === 'interactive') {
    initVideoEngine();
  } else {
    document.addEventListener('DOMContentLoaded', initVideoEngine);
  }
})();
